const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
function inventory(){const root=path.join(__dirname,'..'),assetIndex=JSON.parse(fs.readFileSync(path.join(root,'domestic-assets/index.json'),'utf8')),catalog=JSON.parse(fs.readFileSync(path.join(root,'simulation-assets/catalog.json'),'utf8')),tree=catalog.find(x=>x.id==='tree-standing'),parts=JSON.parse(fs.readFileSync(path.join(root,tree.json),'utf8')),xs=[],zs=[];for(const part of parts)for(let i=0;i<part.positions.length;i+=3){xs.push(part.positions[i]);zs.push(part.positions[i+2]);}return {assetIndex,dimensions:{'tree-standing':{w:2*(Math.max(...xs)-Math.min(...xs)),d:2*(Math.max(...zs)-Math.min(...zs))}}};}
test('preset preflight is deterministic and preserves saved recipes while rejecting unsafe sites',async()=>{
 const {demoStar}=await import('../scripts/diagnose-access-grades.mjs'),{selectSettlementSite}=await import('../settlement-layout.js');const board=demoStar(),before=structuredClone(board),args={layout:board,...inventory(),sites:[{q:0,r:0},{q:-4,r:3}]},a=selectSettlementSite(args),b=selectSettlementSite(args);assert.equal(a.status,'ready');assert.deepEqual(a.site,{q:-4,r:3});assert.equal(a.attempts[0].status,'blocked');assert.equal(a.perCard.filter(c=>c.status==='connected').length,7);assert.deepEqual(a.board,b.board);assert.deepEqual(board,before);assert.deepEqual(a.board.cards,board.cards);for(const key of Object.keys(board.cards))assert.equal(a.board.cards[key],board.cards[key]);assert.equal(a.focusBounds.kind,'occupied-ground');
 const blocked=selectSettlementSite({...args,sites:[{q:0,r:0}]});assert.equal(blocked.status,'blocked');assert(blocked.perCard.some(c=>c.status==='blocked'));
});
test('compact packing preserves rotated multihex footprints and arbitrary card capabilities',async()=>{
 const {compactSettlementLayout}=await import('../settlement-layout.js'),{emptyBoard,editBoard,instanceCells,cardKey}=await import('../playground-model.js');let board=emptyBoard('pack');for(let i=0;i<3;i++)board=editBoard(board,'place',{card:{id:'card'+i,revision:1,rendition:{meshes:[]},cells:i===0?[{q:0,r:0},{q:1,r:0}]:[{q:0,r:0}],capabilities:{}},newInstanceId:'i'+i,q:i*3,r:0,rotation:i});const before=structuredClone(board),packed=compactSettlementLayout(board,{anchorInstanceId:'i0',heroInstanceId:'i2'});assert.deepEqual(board,before);assert.deepEqual(packed.cards,board.cards);assert.deepEqual(packed.instances.map(i=>i.rotation),[0,1,2]);const cells=packed.instances.flatMap(i=>instanceCells(i,packed.cards[cardKey(i.cardId,i.cardRevision)]));assert.equal(new Set(cells.map(c=>c.q+','+c.r)).size,4);assert.deepEqual(packed,compactSettlementLayout(board,{anchorInstanceId:'i0',heroInstanceId:'i2'}));
});
test('missing geometry cannot be certified and out-of-board candidates return blocked receipts',async()=>{
 const {demoStar}=await import('../scripts/diagnose-access-grades.mjs'),{selectSettlementSite}=await import('../settlement-layout.js'),layout=demoStar();assert.throws(()=>selectSettlementSite({layout}),/inventory/);const missing=selectSettlementSite({layout,assetIndex:{},sites:[{q:-4,r:3}]});assert.equal(missing.status,'blocked');assert(missing.warnings.length);const outside=selectSettlementSite({layout,...inventory(),sites:[{q:20,r:20}]});assert.equal(outside.status,'blocked');assert.equal(outside.board,null);assert.equal(outside.attempts.length,1);
});
test('castle burg preflight verifies the actual exterior footprint without inventing production',async()=>{
 const {planSettlementPreset}=await import('../settlement-layout.js'),{settlementPreset}=await import('../settlement-presets.js'),{domesticRecipe,DOMESTIC_SCENES}=await import('../domestic-scenes.js'),{castleRecipe}=await import('../castle-scenes.js'),entries=settlementPreset('burg').entries;
 const cards=entries.map(e=>{const recipe=e.type==='castle'?castleRecipe(e.preset,e.seed):domesticRecipe(e.type,e.preset,e.seed);return {id:e.type,revision:1,rendition:{meshes:[]},cells:[{q:0,r:0}],recipe,capabilities:DOMESTIC_SCENES[e.type]?.capabilities||{}};}),before=structuredClone(cards),result=planSettlementPreset({cards,entries,...inventory(),sites:[{q:-4,r:3}]});
 assert.equal(result.status,'ready',JSON.stringify(result.warnings));assert.equal(result.perCard.length,8);assert(result.perCard.every(c=>c.status==='connected'));assert.deepEqual(result.warnings,[]);const hero=result.perCard.find(c=>c.cardId==='castle');assert.deepEqual(hero.capabilities,{});assert.equal(hero.accessScope,'exterior-only');assert.deepEqual(cards,before);for(const card of cards)assert.equal(result.board.cards[card.id+'@1'],card);assert.equal(result.economy.report.capacities.housing,6);assert.equal(result.board.simulation,null);
});
